USE CATALOG `bc_transit_ws`;
USE SCHEMA `default`;

SELECT COUNT(*) AS stop_visits_analyzed
FROM bc_transit_ws.gold.stop_level_on_time;

USE CATALOG `bc_transit_ws`;
USE SCHEMA `default`;

SELECT ROUND(AVG(ABS(delay_minutes)), 1) AS avg_deviation_min
FROM bc_transit_ws.gold.stop_level_on_time
WHERE delay_minutes IS NOT NULL;

USE CATALOG `bc_transit_ws`;
USE SCHEMA `default`;

SELECT COUNT(DISTINCT route_name) AS routes_tracked
FROM bc_transit_ws.gold.route_on_time_performance;
